import{_ as e,o as t,c as a,Q as i}from"./chunks/framework.b67c47e6.js";const n="/assets/machine-file-concepts.79645d77.svg",g=JSON.parse('{"title":"Machine Files","description":"","frontmatter":{},"headers":[],"relativePath":"guide/machine_files/index.md","filePath":"guide/machine_files/index.md","lastUpdated":1790618281000}'),r={name:"guide/machine_files/index.md"},o=i('<h1 id="machine-files" tabindex="-1">Machine Files <a class="header-anchor" href="#machine-files" aria-label="Permalink to &quot;Machine Files&quot;">​</a></h1><p>A machine file tells a machine what to cut, nail, mill or weld, part by part. produuz.it writes it from the IFC model of your panels, read by your <a href="/guide/management/ifcps/">IFC Parsing Setup</a>, and from how you set up each machine.</p><nav class="table-of-contents"><ul><li><a href="#what-decides-the-file">What decides the file</a></li><li><a href="#where-machine-files-are-made">Where machine files are made</a></li><li><a href="#machines-and-their-files">Machines and their files</a></li><li><a href="#h-m-panel-lines">H&amp;M panel lines</a></li></ul></nav><h2 id="what-decides-the-file" tabindex="-1">What decides the file <a class="header-anchor" href="#what-decides-the-file" aria-label="Permalink to &quot;What decides the file&quot;">​</a></h2><p><img src="'+n+'" alt="Where the settings of a machine file come from"></p><ol><li><strong>Machine file</strong> — the machine&#39;s own configuration file, uploaded once in the machine setup. It says which tools and units the machine has. H&amp;M machines need it.</li><li><strong>Machine setup</strong> — how this machine works: its zero, its orientation, its nailing matrix, its limits, which drawings to make. Set in <strong>Production Settings → Machine Settings</strong>.</li><li><strong>Default job options</strong> — one tab per file type in the machine setup. They fill in the report form, so you set your usual choices once.</li><li><strong>Job options</strong> — the choices for one file, in the report form. They start from the defaults and can be changed for that file only.</li></ol><p>A machine setup is used by a <strong>station</strong> of a production line (panel machines: Mobi One, Frame Station, Robobrick, Isolation) or by a <strong>line</strong> or on its own (saws, cutters, profilers). See <a href="/guide/management/production_lines/#machine-settings">Machine Settings</a>.</p><h2 id="where-machine-files-are-made" tabindex="-1">Where machine files are made <a class="header-anchor" href="#where-machine-files-are-made" aria-label="Permalink to &quot;Where machine files are made&quot;">​</a></h2><table><thead><tr><th>Where</th><th>For</th><th>See</th></tr></thead><tbody><tr><td><strong>Production files → New production file</strong></td><td>Any machine file, for the panels you select. The normal way.</td><td><a href="/guide/reports/">Reports</a></td></tr><tr><td><strong>Run template</strong></td><td>Several files at once, from a generation template.</td><td><a href="/guide/reports/#generation-templates">Generation Templates</a></td></tr><tr><td><strong>Action triggers</strong> and <strong>Launch action</strong></td><td>MOB v2 files made on their own when a design finishes its analysis, or by hand from the designs table.</td><td><a href="/guide/management/production_lines/#automations">Automations</a></td></tr><tr><td><strong>Mobfile Generator</strong></td><td>MOB files from model files that are not in a project.</td><td><a href="/guide/management/tools/">Mobfile Generator</a></td></tr></tbody></table><h2 id="machines-and-their-files" tabindex="-1">Machines and their files <a class="header-anchor" href="#machines-and-their-files" aria-label="Permalink to &quot;Machines and their files&quot;">​</a></h2><table><thead><tr><th>Machine model</th><th>Files</th></tr></thead><tbody><tr><td>H&amp;M Mobi One V1 Station</td><td><a href="/guide/machine_files/formats/panel_mob1/">MOB v1</a></td></tr><tr><td>H&amp;M Mobi One V2 Station</td><td><a href="/guide/machine_files/formats/panel_mob2/">MOB v2</a>, Panel BTLx</td></tr><tr><td>H&amp;M Frame Station V1 / V2</td><td><a href="/guide/machine_files/formats/panel_mob1/">MOB v1</a> / <a href="/guide/machine_files/formats/panel_mob2/">MOB v2</a></td></tr><tr><td>H&amp;M Robi-One Brick Slip Robot</td><td><a href="/guide/machine_files/formats/panel_mob2/">MOB v2</a></td></tr><tr><td>H&amp;M Isolation Machine</td><td><a href="/guide/machine_files/formats/panel_mob2/">MOB v2</a></td></tr><tr><td>H&amp;M Truss Master</td><td><a href="/guide/machine_files/formats/wood_btl/">BTL</a>, BTLx, <a href="/guide/machine_files/formats/generic_wood_csv/">Generic Wood CSV</a></td></tr><tr><td>HUNDEGGER SPEED-Cut, TURBO-Cut</td><td><a href="/guide/machine_files/formats/wood_btl/">BTL</a>, <a href="/guide/machine_files/formats/wood_bvx/">BVX</a>, BTLx, <a href="/guide/machine_files/formats/generic_wood_csv/">Generic Wood CSV</a></td></tr><tr><td>Generic Woods machine</td><td><a href="/guide/machine_files/formats/generic_wood_csv/">Generic Wood CSV</a>, BTLx</td></tr><tr><td>SCM-Gabbiani s95 38</td><td><a href="/guide/machine_files/formats/plates_ardis/">Ardis</a></td></tr><tr><td>Generic Plates machine</td><td><a href="/guide/machine_files/formats/plates_ardis/">Ardis</a>, <a href="/guide/machine_files/formats/plates_xcs/">XCS</a>, <a href="/guide/machine_files/formats/plates_dxf/">DXF</a>, <a href="/guide/machine_files/formats/plates_cix/">CIX</a></td></tr><tr><td>Voortman profiler</td><td><a href="/guide/machine_files/formats/steel_nc/">DSTV .nc</a></td></tr><tr><td>Valk Welding machine</td><td><a href="/guide/machine_files/formats/steel_wiscon/">WISCON</a></td></tr><tr><td>H&amp;M Roofs framing</td><td><a href="/guide/machine_files/formats/frame_mtf/">MTF</a></td></tr><tr><td>H&amp;M Frame nailer</td><td><a href="/guide/machine_files/formats/frame_nailer/">Frame Nailer CSV</a></td></tr><tr><td>STS Steel Frame machine</td><td>STS Steel Frame file</td></tr><tr><td>H&amp;M Mobi One V2 Production Line</td><td>No file: it is the <a href="/guide/management/production_lines/#the-machine-of-a-line">machine of a line</a>.</td></tr></tbody></table><p>Some machine types are licensed: <strong>Machine Settings</strong> shows how many setups you have out of your maximum.</p><h2 id="h-m-panel-lines" tabindex="-1">H&amp;M panel lines <a class="header-anchor" href="#h-m-panel-lines" aria-label="Permalink to &quot;H&amp;M panel lines&quot;">​</a></h2><p>An H&amp;M line has several machine stations, and one MOB file holds the work of all of them for one panel. Start with <a href="/guide/machine_files/formats/panel_mob2/#how-a-file-is-made">How a file is made</a>: it explains how zones decide which station writes which layer, and why the station that builds the frame decides for the whole line. Then set up each machine:</p><ul><li><a href="/guide/machine_files/machines/mobi_one/">Mobi One</a></li><li><a href="/guide/machine_files/machines/frame_station/">Frame Station</a></li><li><a href="/guide/machine_files/machines/robobrick/">Robobrick</a></li><li><a href="/guide/machine_files/machines/isolation/">Isolation machine</a></li></ul>',15),s=[o];function h(d,l,m,f,c,u){return t(),a("div",null,s)}const _=e(r,[["render",h]]);export{g as __pageData,_ as default};
